import{_ as n,l as i,o as e,c as l,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"补丁与 N-day","description":"","frontmatter":{"title":"补丁与 N-day","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/patch-management.md","filePath":"cs/patch-management.md","lastUpdated":1789023840000}'),c={name:"cs/patch-management.md"};function E(A,a,m,_,u,S){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="补丁与-n-day" tabindex="-1">补丁与 N-day <a class="header-anchor" href="#补丁与-n-day" aria-label="Permalink to &quot;补丁与 N-day&quot;">​</a></h1><div class="epigraph"><p>洞一旦公开，时钟对防御方启动。N-day 不是新科学，是补丁滞后、依赖滞后、测试滞后叠成的窗口。优先级应对准暴露面，而不是只对准 CVSS 红字。</p><footer>—— 据 Anderson 对补丁经济学；NIST SP 800-40；对照 CISA KEV 目录的思想</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/cve-cvss">CVSS</a>给了分。缺口是<strong>时间</strong>：已知洞在你系统里还活着。本课收补丁管道与例外，不写 exploit 开发。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>虚拟补丁、WAF、配置关闭可缩窗口，但不能代替供应商补丁。依赖滞后：库已修，镜像未编。缺口是资产清单（SBOM）与暴露面。</p><h3 id="例外要过期" tabindex="-1">例外要过期 <a class="header-anchor" href="#例外要过期" aria-label="Permalink to &quot;例外要过期&quot;">​</a></h3><p>「系统太老不能打」必须有补偿与截止日期。</p><p><span class="marginnote">SP 800-40。CISA KEV：正在被用的已知洞。本课禁止利用 N-day 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：情报→影响分析→测试→部署→验证。对照红队后课：他们吃的就是这窗口。下一课逆向：你如何在没有源码时理解补丁在改什么。</p>',12)),(e(),s(h,null,{default:r(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADV%5B%22%E5%85%AC%E5%91%8A%20%2F%20KEV%22%5D%20--%3E%20AFF%5B%22%E8%B5%84%E4%BA%A7%E6%98%AF%E5%90%A6%E5%8F%97%E5%BD%B1%E5%93%8D%22%5D%0A%20%20AFF%20--%3E%20TEST%5B%22%E6%B5%8B%E8%AF%95%E8%A1%A5%E4%B8%81%22%5D%0A%20%20TEST%20--%3E%20DEP%5B%22%E9%83%A8%E7%BD%B2%22%5D%0A%20%20DELAY%5B%22%E6%BB%9E%E5%90%8E%22%5D%20--%3E%20WIN%5B%22N-day%20%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发现课接到运营。逆向下一课服务「无源码的理解」，不是写恶意软件。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供未授权入侵。逆向工程下一课：方法与法律/合同边界在叙事里点名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分数之后是时钟：公开到修补的窗口。</li><li>SBOM 决定你知不知道自己中招。</li><li>例外必须补偿并过期。</li><li>下一课逆向工程（理解，非利用）。</li><li>出处：NIST SP 800-40；Anderson；CISA KEV。</li></ul>',8))])}const T=n(c,[["render",E]]);export{B as __pageData,T as default};
